{"sql":"-- Create employee_performance table
CREATE TABLE employee_performance (
    employee_id INTEGER REFERENCES "Employee"("EmployeeId"),
    customers_assigned INTEGER,
    performance_score DECIMAL
);"}

{"sql":"-- Reassign employees reporting to Robert King (EmployeeId 7) to Robert's manager (EmployeeId 6)
UPDATE "Employee" SET "ReportsTo" = 6 WHERE "ReportsTo" = 7;

-- Reassign customers supported by Robert King to Robert's manager
UPDATE "Customer" SET "SupportRepId" = 6 WHERE "SupportRepId" = 7;

-- Delete Robert King
DELETE FROM "Employee" WHERE "EmployeeId" = 7;"}

{"sql":"-- Add salary column to Employee table
ALTER TABLE "Employee" ADD COLUMN "Salary" DECIMAL;

-- Promote Laura Callahan and update salaries
UPDATE "Employee" SET "Title" = 'Senior IT Specialist' WHERE "EmployeeId" = 8;
UPDATE "Employee" SET "Salary" = CASE WHEN "EmployeeId" = 8 THEN 75000.00 ELSE 50000.00 END;"}
